#include <bits/stdc++.h>
#define int long long
using namespace std;

int32_t main() {
    int n;
    cin >> n;

    vector<int> v;
    v.push_back(n);

    int sum = n;
    while (sum > 1) {
        bool found = false;

        for (int i = 2; i * i <= sum; ++i) {
            if (sum % i == 0) {
                sum /= i;
                v.push_back(sum);
                found = true;
                break;
            }
        }

        if (!found) {
            v.push_back(1);
            break;
        }
    }

    for (int x : v) {
        cout << x << ' ';
    }

    return 0;
}

